    api.modal('<div class="sheet-head"><div><small class="eyebrow">BEEKEEPING · LEVEL '+(t+1)+' / 3</small><h2>'+names[t]+'</h2></div><button class="close-button" data-close="modal-dialog">×</button></div><img class="hive-preview" src="assets/generated/apiary/hive-'+t+'.webp" alt="'+names[t]+'"><p>Bees forage from fully blooming flower patches within four tiles. Flowers keep helping your hive until you collect their nectar and start their next growing cycle.</p><div class="stats-row"><div class="stat-card"><span>Honey stored</span><b id="hive-amount">'+(h.honey||0)+' / '+capacities[t]+'</b></div><div class="stat-card"><span>Production time</span><b>'+interval(f,h)/1000+' seconds</b></div></div><p id="hive-status" class="sheet-copy">'+statusText(f,h)+'</p><button class="primary-button full-button" id="hive-collect" '+(h.honey?'':'disabled')+'>Collect honey</button><p class="sheet-copy">Sell honey for 30 gold, stock your shop, or bake honey cakes in the farm kitchen. Your hive works while you are away and pauses when its jars are full.</p>'+(t<2?'<button class="small-button full-button" id="hive-upgrade" '+(api.coins()>=cost?'':'disabled')+'>Upgrade hive · '+cost+' gold · '+capacities[t+1]+' jars</button><p class="sheet-copy">Each upgrade adds a new hive box and faster honey production. The ground footprint stays one tile. A new production cycle starts after upgrading.</p>':'<p>Your artisan hive is fully upgraded.</p>'));
    $('#hive-collect').onclick=()=>{if(harvest(f,h))show(h)};
    $('#hive-upgrade')?.addEventListener('click',()=>{if(t>=2||!api.spend(cost))return;settle(f,h);h.tier=t+1;h.lastHoneyAt=Date.now();api.save();api.render();window.meadowAudio?.play('upgrade');show(h)});
