  function readyCount(s){const f=festival(s),r=collectionRewards(s).filter(r=>r.ready&&!r.claimed).length;return Number(!!f?.ready)+r+Number(hasReturn(s));}
  function art(id){const p=api.items[id];return p?.icon?'<img src="'+p.icon+'" alt="">':id==='apple'?'<img src="assets/generated/orchard/apple-fruit.webp" alt="">':'<span aria-hidden="true">'+esc(p?.emoji||'🧺')+'</span>';}
  function pay(r){if(!r)return;api.earn(r.gold);api.xp(r.xp);api.save();api.render();window.meadowAudio?.play('reward');draw(true);}
