 const amount=f=>Object.values(f.shop?.stock||{}).reduce((n,v)=>n+integer(v,1000000000),0);
 function shop(f){f.shop||={unlocked:false,stock:{},earned:0};f.shop.stock||={};if(f.objects.some(o=>o.type==='stall'))f.shop.unlocked=true;return f.shop}
 function plan(f){const p=f.shop?.restockPlan||{},seen=new Set(),rules=[];for(const r of Array.isArray(p.rules)?p.rules:[]){if(!known(r?.id)||seen.has(r.id)||!integer(r.target,capacity(f)))continue;seen.add(r.id);rules.push({id:r.id,target:integer(r.target,capacity(f)),keep:integer(r.keep,9999)});if(rules.length>=limit(f))break}return {enabled:p.enabled===true,rules}}
 function setPlan(f,rules,enabled){if(!Array.isArray(rules)||rules.length>limit(f)||(enabled===true&&!rules.length))return false;const seen=new Set();for(const r of rules){if(!known(r.id)||seen.has(r.id)||!Number.isInteger(r.target)||r.target<1||r.target>capacity(f)||!Number.isInteger(r.keep)||r.keep<0||r.keep>9999)return false;seen.add(r.id)}const s=shop(f);if(!s.unlocked)return false;s.restockPlan={enabled:enabled===true,rules:rules.map(r=>({...r}))};return true}
 function reserve(f,r){let keep=r.keep;for(const area of Object.values(api.state?.()?.farms||{here:f})){if(!area.objects.some(o=>o.type==='stall'))continue;const p=plan(area);if(p.enabled)for(const other of p.rules)if(other.id===r.id)keep=Math.max(keep,other.keep)}return Math.max(keep,window.meadowPlanner?.hold(r.id)||0)}
 function needed(f){const p=plan(f);return p.enabled&&f.objects.some(o=>o.type==='stall')&&amount(f)<capacity(f)&&p.rules.some(r=>(f.inventory[r.id]||0)>reserve(f,r)&&(f.shop?.stock?.[r.id]||0)<r.target)}
 function restock(f,now=Date.now()){
  if(!needed(f))return 0;const p=plan(f),s=shop(f),before=amount(f);let room=Math.max(0,capacity(f)-before),moved=0,start=integer(s.restockCursor,1000000000)%p.rules.length;
  for(let i=0;i<p.rules.length&&room;i++){const r=p.rules[(start+i)%p.rules.length],n=Math.min(room,Math.max(0,r.target-integer(s.stock[r.id],1000000000)),Math.max(0,integer(f.inventory[r.id],1000000000)-reserve(f,r)));if(!n)continue;f.inventory[r.id]-=n;s.stock[r.id]=(s.stock[r.id]||0)+n;room-=n;moved+=n}
  if(moved){s.restockCursor=(start+1)%p.rules.length;if(!before)s.lastSaleAt=now}return moved;
 }
 function helperWork(f){api.settle(f);const n=restock(f);if(n){f.shop.helperStocked=(f.shop.helperStocked||0)+n;api.event('stock',n);api.render()}return n>0}
 function art(id){const p=api.items[id];if(p.icon)return '<img class="product-icon" src="'+p.icon+'" alt="">';if(window.meadowMastery?.crops.includes(id))return '<span class="book-plant"><img src="assets/generated/crop-growth/'+id+'.webp" alt=""></span>';if(id==='apple')return '<img class="product-icon" src="assets/generated/orchard/apple-fruit.webp" alt="">';return '<span class="shop-good-emoji" aria-hidden="true">'+esc(p.emoji||'🧺')+'</span>'}
 function value(f,id){return Math.round(api.items[id].sell*[1,1.05,1.1,1.2][tier(f)]*(window.meadowLife?window.meadowLife.shopFactor(api.state()):1)*(window.meadowProgress?.marketFactor(id)||1))}
 function stockCards(f){if(!f.shop.unlocked)return '<div class="shop-empty"><img src="assets/generated/market-stall.webp" alt="Farm market stall"><h3>A shop of your own</h3><p>Build a market stall to start selling. Then stock your shelves and choose a plan for Farmer Jay.</p></div>';return Object.entries(f.shop.stock).filter(([id,n])=>known(id)&&n>0).map(([id,n])=>'<article class="shop-shelf">'+art(id)+'<div><strong>'+esc(api.items[id].name)+'</strong><small><b data-shelf-count="'+id+'">'+n+'</b> on shelf · '+value(f,id)+' gold each</small></div><button class="small-button" data-shop-take="'+id+'">Take 1</button></article>').join('')||'<div class="shop-empty"><h3>Your shelves are empty</h3><p>Stock goods or let Farmer Jay refill them.</p></div>'}
 function bindTake(){ $$('[data-shop-take]').forEach(b=>b.onclick=()=>{const f=api.current(),s=shop(f),id=b.dataset.shopTake;api.settle(f);if(command('shop.take',{item:id,count:1},refresh))return;if(!(s.stock[id]>0))return refresh();s.stock[id]--;f.inventory[id]=(f.inventory[id]||0)+1;api.save();refresh()}) }
