function shell(html){cleanup();dialog.innerHTML=html;if(!dialog.open)dialog.showModal();$('#fm-close').onclick=()=>run?finish(false,'You stopped this delivery. No goods were taken.'):close();$('#fm-requests').onclick=()=>{if(run)return;close();api.requests()};$('#fm-listen').onclick=()=>window.meadowAudio?.speak('market-welcome')}
