 const overlay=document.createElement('div');overlay.className='fm-result';overlay.setAttribute('role','alertdialog');overlay.innerHTML='<div><h3>Checking your delivery</h3><p class="fm-verified-score"></p><p class="fm-verified-message"></p><button class="primary-button" id="fm-confirm-sale">Check saved delivery</button><button id="fm-return" class="small-button">Back to market</button><button id="fm-home" class="soft-link">Return to farm</button><button id="fm-result-listen" class="small-button">🔊 Jay: result and choices</button></div>';
